# CoreError
# We want to define each variant as a nested class that's also a subclass,
# which is tricky in Python.  To accomplish this we're going to create each
# class separately, then manually add the child classes to the base class's
# __dict__.  All of this happens in dummy class to avoid polluting the module
# namespace.
class CoreError(Exception):
    pass

_UniffiTempCoreError = CoreError

class CoreError:  # type: ignore
    class InvalidInput(_UniffiTempCoreError):
        def __init__(self):
            pass

        def __repr__(self):
            return "CoreError.InvalidInput({})".format(str(self))
    _UniffiTempCoreError.InvalidInput = InvalidInput # type: ignore
    class Locked(_UniffiTempCoreError):
        def __init__(self):
            pass

        def __repr__(self):
            return "CoreError.Locked({})".format(str(self))
    _UniffiTempCoreError.Locked = Locked # type: ignore
    class Authentication(_UniffiTempCoreError):
        def __init__(self):
            pass

        def __repr__(self):
            return "CoreError.Authentication({})".format(str(self))
    _UniffiTempCoreError.Authentication = Authentication # type: ignore
    class Database(_UniffiTempCoreError):
        def __init__(self):
            pass

        def __repr__(self):
            return "CoreError.Database({})".format(str(self))
    _UniffiTempCoreError.Database = Database # type: ignore

CoreError = _UniffiTempCoreError # type: ignore
del _UniffiTempCoreError


class _UniffiConverterTypeCoreError(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return CoreError.InvalidInput(
            )
        if variant == 2:
            return CoreError.Locked(
            )
        if variant == 3:
            return CoreError.Authentication(
            )
        if variant == 4:
            return CoreError.Database(
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if isinstance(value, CoreError.InvalidInput):
            return
        if isinstance(value, CoreError.Locked):
            return
        if isinstance(value, CoreError.Authentication):
            return
        if isinstance(value, CoreError.Database):
            return

    @staticmethod
    def write(value, buf):
        if isinstance(value, CoreError.InvalidInput):
            buf.write_i32(1)
        if isinstance(value, CoreError.Locked):
            buf.write_i32(2)
        if isinstance(value, CoreError.Authentication):
            buf.write_i32(3)
        if isinstance(value, CoreError.Database):
            buf.write_i32(4)



class _UniffiConverterOptionalTypeReadingPosition(_UniffiConverterRustBuffer):
    @classmethod
    def check_lower(cls, value):
        if value is not None:
            _UniffiConverterTypeReadingPosition.check_lower(value)

    @classmethod
    def write(cls, value, buf):
        if value is None:
            buf.write_u8(0)
            return

        buf.write_u8(1)
        _UniffiConverterTypeReadingPosition.write(value, buf)

    @classmethod
    def read(cls, buf):
        flag = buf.read_u8()
        if flag == 0:
            return None
        elif flag == 1:
            return _UniffiConverterTypeReadingPosition.read(buf)
        else:
            raise InternalError("Unexpected flag byte for optional type")



